import React from 'react';
import { Link } from 'react-router-dom';
import '../assets/styles.css';
import '../assets/home-dark.css';
import '../assets/server-theme.css';

import logoNuevo from '../assets/img/logonuevo.png';
import UserMenu from '../components/UserMenu.jsx';

const DISCORD_URL = 'https://discord.rustaco.site';
const STORE_URL = 'https://store.rustaco.co';
const SUPPORT_URL = 'https://discord.rustaco.site';

// ─── EDITA AQUÍ LAS REGLAS ─────────────────────────────────────────────────
const CATEGORIES = [
  {
    id: 'modded',
    icon: 'bi-hdd-stack',
    title: 'Modded',
    desc: 'Reglas del servidor Rustaco.co - Main 2x.',
  },
  {
    id: 'events',
    icon: 'bi-trophy',
    title: 'Events',
    desc: 'Reglas de los eventos in-game y arenas organizadas por el staff.',
  },
];

const RULES = {
  modded: [
    {
      section: 'Grupos',
      icon: 'bi-people',
      rules: [
        {
          title: 'Sin límite de grupo',
          text: 'Rustaco.co - Main 2x no tiene límite de grupo: puedes convivir, farmear y raidear con cuantos jugadores quieras. El staff solo intervendrá ante abusos que arruinen el wipe para el resto del servidor.',
        },
      ],
    },
    {
      section: 'Construcción y raideo',
      icon: 'bi-house-gear',
      rules: [
        {
          title: 'Raideo permitido 24/7',
          text: 'El raid online y offline está permitido en todos los servidores Modded. Juega siempre asumiendo que pueden raidearte.',
        },
        {
          title: 'No griefing extremo',
          text: 'Tras un raid puedes tomar la base, pero no se permite sellar por completo a un jugador dentro de su propia base sin acceso, ni despawnear loot masivamente solo para perjudicar.',
        },
        {
          title: 'No construir en monumentos',
          text: 'No se permite construir dentro de monumentos, bloquear puzzles, cuevas completas ni zonas de spawn para impedir el acceso de otros jugadores.',
        },
      ],
    },
    {
      section: 'Juego limpio',
      icon: 'bi-shield-check',
      rules: [
        {
          title: 'Prohibido el VPN para evadir sanciones',
          text: 'Usar VPN, cuentas alternativas o cualquier método para evadir un ban resulta en ban permanente de la cuenta principal y todas las asociadas.',
        },
        {
          title: 'Game bans recientes',
          text: 'No se permite jugar con cuentas que tengan un game ban de Rust con menos de 180 días de antigüedad, ni convivir con jugadores baneados.',
        },
      ],
    },
  ],
  events: [
    {
      section: 'Arenas y duelos',
      icon: 'bi-crosshair',
      rules: [
        {
          title: 'No teamear en FFA',
          text: 'En arenas free-for-all está prohibido formar equipos, cubrirse entre jugadores o pactar kills. Cada jugador compite por su cuenta.',
        },
        {
          title: 'No farmear estadísticas',
          text: 'Está prohibido inflar kills, KDR o ranking con cuentas secundarias, amigos que se dejan matar o cualquier tipo de boosting. Las stats farmeadas se eliminan del leaderboard.',
        },
        {
          title: 'Permanece en la zona del evento',
          text: 'No se permite salir del área designada de la arena, esconderse fuera de los límites ni abusar de zonas inaccesibles para otros jugadores.',
        },
      ],
    },
    {
      section: 'Eventos in-game',
      icon: 'bi-calendar-event',
      rules: [
        {
          title: 'Respeta el formato del evento',
          text: 'Cada evento tiene reglas propias anunciadas en Discord antes de comenzar. Participar implica aceptarlas; incumplirlas conlleva descalificación.',
        },
        {
          title: 'No sabotear eventos',
          text: 'Interferir intencionalmente en un evento en el que no participas (matar participantes, bloquear zonas, robar premios) está sancionado.',
        },
        {
          title: 'Decisiones del staff',
          text: 'Las decisiones del staff durante un evento son definitivas. Si crees que hubo un error, abre un ticket en Discord después del evento con tu evidencia.',
        },
      ],
    },
  ],
};

// Reglas que aplican a TODOS los servidores de la red
const NETWORK_RULES = {
  section: 'Reglas generales de Rustaco',
  icon: 'bi-globe-americas',
  rules: [
    {
      title: 'Cero tolerancia al cheating',
      text: 'Cheats, scripts, macros, ESP o cualquier ventaja externa resultan en ban permanente e irrevocable en toda la red. Convivir o compartir base con un cheater también es sancionable.',
    },
    {
      title: 'Toxicidad extrema',
      text: 'Racismo, doxxing, amenazas reales y acoso dirigido no tienen lugar en Rustaco, ni en el juego ni en Discord. El chat competitivo y los piques normales del juego están bien; cruzar esa línea no.',
    },
    {
      title: 'Abuso de bugs y exploits',
      text: 'Aprovechar bugs del juego o de plugins para obtener ventaja está prohibido. Si encuentras uno, repórtalo en Discord; los reportes pueden ser recompensados.',
    },
